#!/bin/sh

# ./test.sh [OPTIONS] [FILENAMES...]
#
# Options:
#   -first       Stop on first failed test
#   -verifyIR    Verify the IR code generated by llvm. Also enables
#                the -first option.
#   -blacklisted Run tests from the blacklisted directory and report
#                passed tests instead of failed tests.
#
# Run test(s) optionally using FILENAMES as input. Compare the output to the file
# with the same filename except with the ".result" extension.
#
# FILENAMES is the list of optional names of the logo script WITH the .lg extension.
#
# If FILENAMES is not specified then this will go through all the .lg files
# in the tests directory.

stop_on_first_failure=false
blacklisted=false
verify_ir=false

# Parse options
while [ $# -gt 0 ]; do
    case $1 in
        -first)
            stop_on_first_failure=true
            shift
            ;;
        -verifyIR)
            verify_ir=true
            stop_on_first_failure=true
            shift
            ;;
        -blacklisted)
            blacklisted=true
            shift
            ;;
        *)
            break
            ;;
    esac
done
# Remaining arguments are filenames
saved_filenames="$*"
saved_argc=$#

# Change to the directory of the test script.
test_dir=$(dirname $0)
if [ "$blacklisted" = true ]; then
    cd $test_dir/blacklisted
else
    cd $test_dir/tests
fi

logo_binary=qlogo
logo_path=""
for candidate in \
    "../../../build/qlogo/$logo_binary" \
    "../../$logo_binary" \
    "../../../qlogo/$logo_binary" \
    "$logo_binary"
do
    if [ -x "$candidate" ] 2>/dev/null; then
        logo_path="$candidate"
        break
    fi
done
if [ -z "$logo_path" ] && command -v "$logo_binary" >/dev/null 2>&1; then
    logo_path=$(command -v "$logo_binary")
fi
if [ -n "$logo_path" ]; then
    case $logo_path in
        /*) ;;
        *)
            logo_dir=$(dirname "$logo_path")
            logo_base=$(basename "$logo_path")
            logo_path=$(cd "$logo_dir" && pwd)/$logo_base
            ;;
    esac
fi
reported_tests=""

exe_opts=""
if [ "$verify_ir" = true ]; then
    exe_opts="--verifyIR"
fi

run_test() {
    f="$1"
    case $f in
        *.lg)
            echo $f
            $logo_path $exe_opts < $f 2>&1 | diff "${f%.lg}.result" -
            if [ $? -eq 1 ]
            then
                if [ "$blacklisted" != true ] && [ "$stop_on_first_failure" = true ]; then
                    exit 1
                fi
                reported_tests="$reported_tests$f
"
            else
                if [ "$blacklisted" = true ]; then
                    reported_tests="$reported_tests$f
"
                fi
            fi
            ;;
    esac
}

if [ -z "$logo_path" ]
then
    echo "Error: could not find executable '$logo_binary'."
    exit 0
fi

# Check if system has GNU date (supports %N for nanoseconds)
has_gnu_date() {
    # GNU date supports --version, BSD date doesn't
    if date --version >/dev/null 2>&1 && date --version 2>&1 | grep -q "GNU"; then
        return 0
    fi
    return 1
}

if [ $saved_argc -gt 0 ]
then
    for filename in $saved_filenames
    do
        run_test $filename
    done
else
    if has_gnu_date; then
        start_time=`date +%s%3N`
    fi
    test_count=0
    
    # Create temporary files for collecting test results and driving make.
    reported_test_file=$(mktemp /tmp/test_reported_XXXXXX)
    test_makefile=$(mktemp /tmp/test_makefile_XXXXXX)

    if ! command -v make >/dev/null 2>&1; then
        echo "Error: make is required but was not found in PATH."
        rm -f "$reported_test_file" "$test_makefile"
        exit 1
    fi

    if ! make --version >/dev/null 2>&1 || ! make --version 2>&1 | grep -q "GNU Make"; then
        echo "Error: GNU make is required but was not found."
        rm -f "$reported_test_file" "$test_makefile"
        exit 1
    fi

    # Generate a Makefile with one target per .lg file. Test targets use a
    # run- prefix so they do not collide with the .lg source files on disk.
    # -Otarget keeps each test's header and diff output grouped.
    {
        echo "LOGO = $logo_path"
        if [ -n "$exe_opts" ]; then
            echo "EXE_OPTS = $exe_opts"
        else
            echo "EXE_OPTS ="
        fi
        echo "REPORT = $reported_test_file"
        echo "BLACKLISTED = $blacklisted"
        echo
        echo ".PHONY: all"
        printf "all:"
        for a in *.lg; do
            [ -f "$a" ] || continue
            printf " run-%s" "$a"
            test_count=$((test_count + 1))
        done
        echo
        echo
        cat <<'MAKEEOF'
run-%.lg:
	@echo "==== $(patsubst run-%,%,$@)"
	@$(LOGO) $(EXE_OPTS) < $(patsubst run-%,%,$@) 2>&1 | diff "$(patsubst run-%.lg,%.result,$@)" -; \
	exit_code=$$?; \
	if [ "$(BLACKLISTED)" = true ]; then \
		if [ $$exit_code -eq 0 ]; then echo "$(patsubst run-%,%,$@)" >> $(REPORT); fi; \
		exit 0; \
	elif [ $$exit_code -eq 1 ]; then \
		echo "$(patsubst run-%,%,$@)" >> $(REPORT); \
		exit 1; \
	else \
		exit $$exit_code; \
	fi
MAKEEOF
    } > "$test_makefile"

    # Run all tests in parallel. Use -k unless -first is set (then stop after the
    # first failure, once in-flight jobs finish).
    make_opts="-j$(nproc) -Otarget"
    if [ "$blacklisted" = true ] || [ "$stop_on_first_failure" != true ]; then
        make_opts="$make_opts -k"
    fi
    # shellcheck disable=SC2086
    make -f "$test_makefile" $make_opts all

    rm -f "$test_makefile"

    # Read test results from the temporary file
    if [ -f "$reported_test_file" ] && [ -s "$reported_test_file" ]; then
        reported_tests=$(cat "$reported_test_file")
    fi
    rm -f "$reported_test_file"
    
    if has_gnu_date; then
        end_time=`date +%s%3N`
        trt=$((end_time-start_time))
    fi

    if [ -n "$reported_tests" ]; then
        echo
        echo "============================"
        if [ "$blacklisted" = true ]; then
            echo "====" PASSED TESTS:
        else
            echo "====" FAILED TESTS:
        fi
        echo "===="
        echo "$reported_tests" | while IFS= read -r f; do
            echo "====" $f
            echo "===="
        done
        echo "============================"
    fi

    echo $test_count tests.
    if has_gnu_date; then
        echo Total Running time: ${trt} milliseconds
    fi
fi

# Exit with error code if not blacklisted and there are reported tests
if [ "$blacklisted" != true ] && [ -n "$reported_tests" ]; then
    exit 1
fi
exit 0
